-- --------------------------------------------------------

--
-- Table structure for table `client_lawyers`
--

DROP TABLE IF EXISTS `client_lawyers`;
CREATE TABLE IF NOT EXISTS `client_lawyers` (
  `id` int NOT NULL AUTO_INCREMENT,
  `client_id` int NOT NULL,
  `lawyer_id` int NOT NULL,
  `is_primary` tinyint(1) DEFAULT '0' COMMENT 'Indicates if this is the primary lawyer for the client',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_client_lawyer` (`client_id`,`lawyer_id`),
  KEY `idx_client_id` (`client_id`),
  KEY `idx_lawyer_id` (`lawyer_id`),
  KEY `idx_is_primary` (`is_primary`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=4097 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

